type QueuedChange = {
  id: string;
  stopId: string;
  field: "status" | "signature" | "note";
  value: string;
  changedAt: number;
};

export async function replay(queue: QueuedChange[]) {
  for (const change of queue.sort((a, b) => a.changedAt - b.changedAt)) {
    await api.applyChange(change);
  }
}
